INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_mat-zlomky-pocitani_0','Kolik je 1/5 + 2/5?',ARRAY['2/5','3/5','3/10','1/5']::TEXT[],1,'Jmenovatel zůstává, čitatele sečteme: 1 + 2 = 3.',1,ARRAY[]::TEXT[],NULL,0,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_1','Kolik je 3/4 − 1/4?',ARRAY['1/4','2/4','2/8','4/4']::TEXT[],1,'Jmenovatel zůstává, čitatele odečteme: 3 − 1 = 2.',1,ARRAY[]::TEXT[],NULL,1,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_2','Který zlomek je větší: 3/8, nebo 5/8?',ARRAY['Jsou stejné','3/8','Nedá se říct','5/8']::TEXT[],3,'Při stejném jmenovateli je větší ten s větším čitatelem.',1,ARRAY[]::TEXT[],NULL,2,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_3','Kolik je 2/7 + 4/7?',ARRAY['6/14','8/7','2/7','6/7']::TEXT[],3,'2 + 4 = 6, jmenovatel zůstává 7.',2,ARRAY[]::TEXT[],NULL,3,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_4','Kolik je 5/6 − 2/6?',ARRAY['10/6','3/12','3/6','7/6']::TEXT[],2,'5 − 2 = 3.',2,ARRAY[]::TEXT[],NULL,4,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_5','Zlomek 1/2 zapsaný se jmenovatelem 4 je…',ARRAY['4/2','3/4','2/4','1/4']::TEXT[],2,'Rozšíříme dvěma: 1/2 = 2/4.',2,ARRAY[]::TEXT[],NULL,5,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_6','Kolik je 3/8 + 1/2?',ARRAY['7/8','5/8','4/8','4/10']::TEXT[],0,'1/2 = 4/8 a 3/8 + 4/8 = 7/8.',3,ARRAY[]::TEXT[],NULL,6,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_7','Zkrať zlomek 6/8.',ARRAY['2/8','3/4','1/2','6/4']::TEXT[],1,'Dělíme čitatele i jmenovatele dvěma.',3,ARRAY[]::TEXT[],NULL,7,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_8','Kolik je 7/10 − 3/10?',ARRAY['4/10','10/10','3/10','4/20']::TEXT[],0,'7 − 3 = 4.',3,ARRAY[]::TEXT[],NULL,8,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_9','Kolik je 1/3 + 1/6?',ARRAY['1/2','2/6','2/9','1/3']::TEXT[],0,'1/3 = 2/6, 2/6 + 1/6 = 3/6 = 1/2.',4,ARRAY[]::TEXT[],NULL,9,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_10','Který zlomek je největší: 2/3, 3/4, 5/8?',ARRAY['5/8','Jsou stejné','2/3','3/4']::TEXT[],3,'Převedeme na 24: 16/24, 18/24, 15/24.',4,ARRAY[]::TEXT[],NULL,10,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_11','Kolik je 1 − 3/7?',ARRAY['2/7','7/3','4/7','3/7']::TEXT[],2,'1 = 7/7 a 7/7 − 3/7 = 4/7.',4,ARRAY[]::TEXT[],NULL,11,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_12','Jana snědla 1/4 pizzy a Petr 2/4. Kolik pizzy zbylo?',ARRAY['0','3/4','1/4','2/4']::TEXT[],2,'1 − 3/4 = 1/4.',5,ARRAY[]::TEXT[],NULL,12,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_13','Kolik je 5/6 + 2/3?',ARRAY['1 a 1/3','7/9','1 a 1/2','7/6']::TEXT[],2,'2/3 = 4/6 a 5/6 + 4/6 = 9/6 = 1 a 1/2.',5,ARRAY[]::TEXT[],NULL,13,'c_mat-zlomky-pocitani',NULL,NOW()),
('q_mat-zlomky-pocitani_14','Nádrž byla z 5/8 plná a spotřebovalo se 2/8. Kolik zbylo?',ARRAY['3/16','5/8','3/8','7/8']::TEXT[],2,'5/8 − 2/8 = 3/8.',5,ARRAY[]::TEXT[],NULL,14,'c_mat-zlomky-pocitani',NULL,NOW()),
